<?php
require __DIR__ . '/backend/common.php'; require_admin(); $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { try { $id=(int) input('id'); $decision=input('decision'); if (!in_array($decision,['approved','rejected'],true)) throw new InvalidArgumentException('Invalid decision.'); $paper=$conn->execute_query("SELECT user_id,title FROM papers WHERE id=? AND status='pending'",[$id])->fetch_assoc(); if(!$paper) throw new InvalidArgumentException('Paper is no longer pending.'); $conn->execute_query('UPDATE papers SET status=? WHERE id=?',[$decision,$id]); notify_user($paper['user_id'],'Your paper “'.$paper['title'].'” was '.$decision.'.'); flash('Paper '.$decision.'.'); go('admin-paper-reviews.php'); } catch(Throwable $e){$error=page_error($e);} }
$papers=$conn->query("SELECT p.*,u.full_name,u.email FROM papers p JOIN users u ON u.id=p.user_id WHERE p.status='pending' ORDER BY p.created_at")->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Paper Reviews · Admin</title><link rel="stylesheet" href="portal.css"></head><body class="portal-page"><div class="app-container portal-layout"><?php require __DIR__.'/backend/sidebar.php'; ?><main class="main-content"><div class="live-content"><h1>Paper reviews</h1><p>Review each submitted paper before it becomes visible in the research collection.</p><?php require __DIR__.'/backend/admin_nav.php'; ?><?php if($error): ?><p class="notice error"><?= e($error) ?></p><?php endif; ?><?php if(!$papers): ?><p class="box empty">The paper review queue is clear.</p><?php endif; ?><?php foreach($papers as $paper): ?><article class="box"><span class="tag">Awaiting editorial review</span><h2><?= e($paper['title']) ?></h2><p class="muted">Submitted by <?= e($paper['full_name']) ?> · <?= e($paper['department']) ?> · <?= e($paper['created_at']) ?></p><p><?= nl2br(e($paper['abstract'])) ?></p><p><strong>Keywords:</strong> <?= e($paper['keywords']) ?></p><p><?php if($paper['file_path']): ?><a href="download.php?type=paper&amp;id=<?= (int)$paper['id'] ?>">Review submitted PDF</a><?php else: ?><span class="muted">No attached PDF.</span><?php endif; ?></p><form method="post"><input type="hidden" name="id" value="<?= (int)$paper['id'] ?>"><button name="decision" value="approved">Approve publication</button> <button class="danger" name="decision" value="rejected">Reject</button></form></article><?php endforeach; ?></div></main></div></body></html>
